// Generated country catalog containing ISO-3166 codes and localized names.
class CountryCatalogItem {
  final String code;
  final String englishName;
  final String spanishName;
  final String portugueseName;

  const CountryCatalogItem({
    required this.code,
    required this.englishName,
    required this.spanishName,
    required this.portugueseName,
  });

  String getName(String locale) {
    switch (locale.substring(0, 2).toLowerCase()) {
      case 'es':
        return spanishName;
      case 'pt':
        return portugueseName;
      default:
        return englishName;
    }
  }
}

